INSERT INTO `sugestoes` (`id`, `user_nif`, `categoria`, `titulo`, `descricao`, `prioridade`, `estado`, `resposta`, `respondido_por`, `respondido_em`, `created_at`, `updated_at`) VALUES
(3, 211091073, 'Melhoria', 'Campo \"Data de aquisição\"', 'Para que serve?', 'media', 'implementada', 'Será corrigida da versão 0.0.2', 1, '2025-10-27 21:03:06', '2025-10-26 19:49:04', '2025-10-27 21:03:06'),
(4, 202570770, 'Melhoria', 'Pemuta', '- Permuta comigo própria- acrescentar horário e sala??\n- (Supervisor) Comecei por rejeitar a permuta e posteriormente aceitei e desapareceu da listagem .', 'media', 'implementada', 'Implementada V 0.0.3 \nContinuar a validar as rejeitadas', 1, '2025-10-28 22:25:54', '2025-10-28 11:31:31', '2025-10-28 22:25:54'),
(5, 194341402, 'Interface', 'ver escaloes', 'ver escaloes dos alunos no kit digital', 'media', 'implementada', 'A funcionar', 1, '2026-01-07 14:06:06', '2026-01-05 10:29:53', '2026-01-07 14:06:06'),
(6, 194341402, 'Melhoria', 'Registo de envio de email', 'Quando se reenvia email de aviso de levantamento deve ficar registado nas OBS', 'baixa', 'pendente', NULL, NULL, NULL, '2026-01-07 08:21:57', '2026-01-07 08:21:57'),
(7, 194341402, 'Bug/Erro', 'Criação de ano lectivo', 'Criação de ano lectivo', 'baixa', 'implementada', 'A funcionar', 1, '2026-01-07 14:05:48', '2026-01-07 08:44:06', '2026-01-07 14:05:48'),
(8, 213901218, 'Melhoria', 'Grupo de recrutamento', 'À frente do nome de cada professor colocar o seu grupo de recrutamento', 'alta', 'implementada', 'podes testar sff', 1, '2026-02-20 19:21:05', '2026-02-20 15:10:26', '2026-02-20 19:21:05'),
(9, 213901218, 'Melhoria', 'Nº de vigilância por vigilante', 'Nas convocatórias, à frente do nome de cada professor, ter o número de vigilâncias já efetuadas.', 'alta', 'implementada', 'podes testar sff', 1, '2026-02-20 19:20:54', '2026-02-20 15:12:23', '2026-02-20 19:20:54'),
(10, 213901218, 'Bug/Erro', 'antecedência da comparência dos vigilantes', 'Corrigir: \"Todos os docentes convocados devem comparecer com 45 minutos de\nantecedência ao horário de início do exame para receber as instruções necessárias.\"\nÉ 45 minutos antes, não 30 minutos\n', 'alta', 'implementada', 'podes testar sff', 1, '2026-02-20 19:20:42', '2026-02-20 15:18:19', '2026-02-20 19:20:42'),
(11, 213901218, 'Bug/Erro', 'duração das provas-ensaio', 'As Provas-Ensaio têm duração de 45 minutos e não têm tolerância', 'alta', 'implementada', 'A Duração de cada prova pode ser alterado no lápis em  https://escoladigital.cloud/sessoes-exame', 1, '2026-02-20 19:02:02', '2026-02-20 15:21:15', '2026-02-20 19:02:02'),
(12, 213901218, 'Melhoria', 'permutas', 'No pedido de permuta pelo vigilante, ir a informação da duração da prova e do prazo limite de aceitação da permuta (até 24 horas antes da realização da prova).\n\nSubstituir a expressão \"professor original\" por \"professor convocado\"\n\n', 'alta', 'implementada', 'podes testar sff', 1, '2026-02-20 19:20:28', '2026-02-20 15:45:00', '2026-02-20 19:20:28'),
(13, 213901218, 'Bug/Erro', 'autorização de permutas', 'Após a aprovação do secretariado de exames de uma permuta, o professor original recebe mail  com informação: \"✓ A convocatória foi atualizada automaticamente. Sílvia Faim é agora o responsável pela vigilância.\n\nVer Convocatórias\".\nAo carregar em \"Ver Convocatórias\" dá erro: \" Whoops!\nWe seem to have hit a snag. Please try again later...\"', 'alta', 'implementada', 'Por favor validar com nova convocatória. Ignorar esse email já gerado.', 1, '2026-02-23 12:34:44', '2026-02-20 15:51:26', '2026-02-23 12:34:44'),
(14, 213901218, 'Melhoria', 'número de suplentes a convcar', 'Abrindo uma sessão para suplentes, exige que se coloquem 2, mas pode ser um número diferente', 'media', 'implementada', 'sem restrição de convocados', 1, '2026-02-25 17:44:55', '2026-02-24 12:35:05', '2026-02-25 17:44:55'),
(15, 213901218, 'Melhoria', 'Documento para assinar no inicio e final das vigilâncias', 'Criar o documento que os convocados têm que assinar no inicio e final das vigilâncias', 'alta', 'implementada', 'Disponivel em \"marcar presenças\"', 1, '2026-02-25 17:45:24', '2026-02-24 12:39:07', '2026-02-25 17:45:24'),
(16, 213901218, 'Melhoria', 'Ordenação de Sessão Exames', 'Em Sessão Exames, haver a possibilidade de aparecer por ordem cronológica, ou ordem crescente( ou decrescente) de código.', 'media', 'rejeitada', 'Já existe filtros de ordenação', 1, '2026-02-25 17:45:53', '2026-02-24 12:44:40', '2026-02-25 17:45:53'),
(17, 213901218, 'Melhoria', 'Férias dos professores', 'Acrescentar o período em que  cada professor está de férias, para não ser convocado nessas datas', 'media', 'pendente', NULL, NULL, NULL, '2026-02-25 11:00:25', '2026-02-25 11:00:25'),
(18, 213901218, 'Melhoria', 'Número de vigilantes por sala', 'No prova ensaio, haverá 6 alunos na biblioteca que precisam de leitura de prova. Preciso de aí colocar mais vigilantes, mas só aceita 1.', 'alta', 'implementada', 'Novas sala criadas. Bib, Bib2...', 1, '2026-03-10 15:43:30', '2026-03-10 13:14:58', '2026-03-10 15:43:30'),
(19, 213901218, 'Melhoria', 'Procurar nome de vigilante', 'Quando procuro o nome dos vigilantes, por exemplo, \"Ana Queiroz\": Escrevo \"Ana\" e aparecem todas as Anas. Tenho que percorrê-las até encontrar a Queiroz. Se escrever \"Ana Queiroz\" não aparece nada. ', 'media', 'rejeitada', 'Pesquisa apenas por um nome', 1, '2026-03-10 15:43:53', '2026-03-10 13:35:03', '2026-03-10 15:43:53'),
(20, 213901218, 'Melhoria', 'Tempo de antecedência dos vigilantes', 'No pdf das convocatórias, alterar o tempo que os docentes têm que comparecer antecedência para 45 minutos.', 'media', 'pendente', NULL, NULL, NULL, '2026-03-10 14:56:26', '2026-03-10 14:56:26');
